let selectedPage = 'root';
let selectedTrail = ['root'];
let branchScenario = 'normal';
let branchCount = 2;
const expanded = new Set(['root/architecture']);
const esc = (text) => String(text).replace(/[&<>"']/g, (char) => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[char]));
const occurrence = (trail) => trail.join('/');
function pageLink(key, trail, classes = '') {
  const page = pages[key];
  return `<a class="${classes}" href="#page-${key}" data-page="${key}" data-trail="${occurrence(trail)}">${esc(page.title)}</a>`;
}
function categoryChildren(key) {
  if (key !== 'demo') return pages[key].children || [];
  if (branchScenario === 'empty') return [];
  return branchScenario === 'more' ? pages.demo.children.slice(0, branchCount) : pages.demo.children.slice(0, 2);
}
function treeRow(key, trail) {
  const page = pages[key], path = occurrence(trail), open = expanded.has(path), active = path === occurrence(selectedTrail);
  const category = page.kind === 'catalog';
  const id = `children-${path.replaceAll('/', '-')}`;
  let body = '';
  if (category && open) {
    if (key === 'demo' && ['empty', 'loading', 'failed'].includes(branchScenario)) {
      const status = branchScenario === 'empty' ? '<p class="px-2 py-2 mb-0 text-body-secondary" role="status">Нет страниц</p>' : branchScenario === 'loading' ? '<p role="status">Загрузка…</p><button class="btn btn-outline-light btn-sm" data-demo-action="finish">Завершить демо-загрузку</button>' : '<p role="alert" data-error-code="demo_branch_failed">Не удалось загрузить категорию</p><button class="btn btn-outline-light btn-sm" data-demo-action="retry">Retry</button>';
      body = `<li class="nav-item px-2 py-2" id="demo-branch" data-state="${branchScenario}" aria-busy="${branchScenario === 'loading'}">${status}</li>`;
    } else {
      body = categoryChildren(key).map((child) => treeRow(child, [...trail, child])).join('');
      if (key === 'demo') body = `<li id="demo-branch" class="nav-item" data-state="${branchScenario === 'demo' ? 'normal' : branchScenario}" aria-busy="false"><ul class="nav flex-column">${body}${branchScenario === 'more' && branchCount < 4 ? '<li class="nav-item px-2 py-2"><button class="btn btn-outline-light btn-sm" data-demo-action="more">More pages</button></li>' : ''}</ul></li>`;
    }
  }
  return `<li class="nav-item" data-occurrence="${path}"><div class="d-flex align-items-start">${category ? `<button class="btn btn-sm btn-link text-light flex-shrink-0 category-toggle" data-toggle-category="${path}" aria-controls="${id}" aria-expanded="${open}" aria-label="${open ? 'Свернуть' : 'Раскрыть'} ${esc(page.title)}">${open ? '▾' : '▸'}</button>` : '<span class="category-spacer" aria-hidden="true"></span>'}${pageLink(key, trail, `nav-link flex-grow-1 text-break${active ? ' active' : ''}`)}</div>${category ? `<ul id="${id}" class="nav nav-treeview flex-column ps-3${open ? ' d-block' : ''}"${open ? '' : ' hidden'}>${body}</ul>` : ''}</li>`;
}
function markSelected() {
  document.querySelectorAll('#wiki-tree [data-page]').forEach((link) => {
    const active = link.dataset.trail === occurrence(selectedTrail);
    link.classList.toggle('active', active);
    if (active) link.setAttribute('aria-current', 'page'); else link.removeAttribute('aria-current');
    link.classList.toggle('category-ancestor', selectedTrail.slice(0, -1).some((_, i) => occurrence(selectedTrail.slice(0, i + 1)) === link.dataset.trail));
  });
}
function buildTree() {
  const scroll = $('#tree-scroll').scrollTop;
  $('#wiki-tree').innerHTML = `<li class="nav-item">${pageLink('root', ['root'], 'nav-link text-break')}</li>` + pages.root.children.map((key) => treeRow(key, ['root', key])).join('') + (branchScenario === 'normal' ? '' : '<li class="nav-header">Демонстрационный пример</li>' + treeRow(branchScenario === 'nested' ? 'team' : 'demo', ['root', branchScenario === 'nested' ? 'team' : 'demo']));
  markSelected();
  $('#tree-scroll').scrollTop = scroll;
}
function members(key) {
  const list = categoryChildren(key);
  return [['catalog', 'Подкатегории'], ['page', 'Страницы']].map(([kind, title]) => {
    const items = list.filter((child) => pages[child].kind === kind);
    return items.length ? `<section class="mt-4" data-members="${kind}"><h2 id="members-${kind}">${title}</h2><ul>${items.map((child) => `<li class="mb-2">${pageLink(child, [...selectedTrail, child])}</li>`).join('')}</ul></section>` : '';
  }).join('') || '<p class="mt-4" data-member-state="empty">В этой категории пока нет страниц.</p>';
}
function renderPage(key, trail) {
  const page = pages[key];
  if (!page) {
    $('#demo-feedback').hidden = false;
    $('#demo-feedback').dataset.code = 'demo_page_unavailable';
    $('#demo-feedback').textContent = 'Страница отсутствует в локальном наборе. Текущая статья сохранена.';
    return false;
  }
  selectedPage = key;
  // The clicked category occurrence supplies context; filenames never invent ancestry.
  selectedTrail = trail || (key === 'root' ? ['root'] : ['root', key]);
  $('#demo-feedback').hidden = true;
  $('#article').dataset.pageId = page.id;
  $('#article').dataset.pageKind = page.kind;
  $('#article-title').textContent = page.title;
  $('#page-path').innerHTML = selectedTrail.map((part, i) => `<li class="breadcrumb-item${i === selectedTrail.length - 1 ? ' active' : ''}"${i === selectedTrail.length - 1 ? ' aria-current="location"' : ''}>${i === selectedTrail.length - 1 ? esc(pages[part].title) : pageLink(part, selectedTrail.slice(0, i + 1))}</li>`).join('');
  $('#article-body').innerHTML = page.content + (page.kind === 'catalog' ? members(key) : '');
  $('#article-body').querySelectorAll('table').forEach((table) => {
    const scroll = document.createElement('div');
    scroll.className = 'table-responsive';
    table.replaceWith(scroll); scroll.append(table);
  });
  markSelected();
  $('#outline').innerHTML = [...$('#article-body').querySelectorAll('h2[id],h3[id]')].map((heading) => `<li class="mb-2"><a href="#${heading.id}">${esc(heading.textContent)}</a></li>`).join('');
  $('#source-records').innerHTML = page.sources.length ? page.sources.map((source) => `<section class="border-top pt-3 mt-3" data-revision-state="${source.text ? 'saved' : 'unavailable'}"><h3 class="h6 text-break">${source.name}</h3><p>Принятая ревизия: <code>${source.revision}</code></p>${source.text ? `<details><summary>Сохранённый текст · демо</summary><pre class="text-wrap mt-2">${esc(source.text)}</pre><p class="text-body-secondary">Локальный образец принятого текста. Оригинал не запрашивается.</p></details>` : '<p role="status">Сохранённый текст ревизии недоступен в демо.</p>'}</section>`).join('') : '<p data-source-state="empty">Для этой страницы не записаны источники.</p>';
  $('#page-details').innerHTML = `<dt>PageID</dt><dd><code>${page.id}</code></dd><dt>Путь файла</dt><dd>${page.path}</dd><dt>Данные</dt><dd>Локальный демонстрационный набор</dd><dt>Источников</dt><dd>${page.sources.length}</dd>`;
  return true;
}
// Native AdminLTE sidebar + Bootstrap context drawer; add focus and exclusivity.
const sidebar = $('#wiki-navigation'), sidebarButton = $('#navigation-toggle'), context = $('#page-context');
const contextDrawer = bootstrap.Offcanvas.getOrCreateInstance(context);
const mobile = () => matchMedia('(max-width: 991.98px)').matches;
const pushMenu = () => adminlte.PushMenu.getOrCreateInstance(sidebar);
let sidebarReturnFocus = true;
function sidebarAccess() {
  const open = document.body.classList.contains('sidebar-open');
  sidebar.inert = mobile() && !open;
  sidebar.setAttribute('aria-hidden', String(mobile() && !open));
  sidebarButton.setAttribute('aria-expanded', String(open));
  $('.app-main').inert = mobile() && open;
  $('.app-header').inert = mobile() && open;
}
sidebar.addEventListener('open.lte.push-menu', () => contextDrawer.hide());
sidebar.addEventListener('opened.lte.push-menu', () => { sidebarAccess(); if (mobile()) $('#navigation-close').focus(); });
sidebar.addEventListener('collapsed.lte.push-menu', () => {
  sidebarAccess();
  if (mobile() && sidebarReturnFocus) sidebarButton.focus();
  sidebarReturnFocus = true;
});
context.addEventListener('show.bs.offcanvas', () => { if (mobile() && document.body.classList.contains('sidebar-open')) pushMenu().collapse(); });
context.addEventListener('hidden.bs.offcanvas', () => { if (innerWidth < 1200) $('#context-toggle').focus(); });
matchMedia('(min-width: 992px)').addEventListener('change', sidebarAccess);
sidebarAccess();
document.addEventListener('keydown', (event) => {
  if (!mobile() || !document.body.classList.contains('sidebar-open')) return;
  if (event.key === 'Escape') { event.preventDefault(); pushMenu().collapse(); }
  if (event.key === 'Tab') {
    const focusable = [...sidebar.querySelectorAll('a,button,summary')].filter((element) => element.getClientRects().length > 0);
    const first = focusable[0], last = focusable.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
  }
});
document.addEventListener('click', (event) => {
  const toggle = event.target.closest('[data-toggle-category]');
  if (toggle) {
    const path = toggle.dataset.toggleCategory;
    if (expanded.has(path)) expanded.delete(path); else expanded.add(path);
    buildTree();
    $(`[data-toggle-category="${path}"]`).focus({preventScroll: true});
    return;
  }
  const page = event.target.closest('[data-page]');
  if (page) {
    event.preventDefault();
    if (!renderPage(page.dataset.page, page.dataset.trail?.split('/'))) return;
    if (mobile() && document.body.classList.contains('sidebar-open')) {
      sidebarReturnFocus = false;
      pushMenu().collapse();
      $('#article-title').focus({preventScroll: true});
    }
    $('#article').scrollIntoView({block: 'start'});
    return;
  }
  const action = event.target.closest('[data-demo-action]');
  if (action) {
    if (action.dataset.demoAction === 'more') branchCount = 4;
    else { branchScenario = 'demo'; branchCount = 2; $('#branch-scenario').value = 'demo'; }
    buildTree();
    $('#demo-branch a')?.focus({preventScroll: true});
  }
  const anchor = event.target.closest('#outline a');
  if (anchor && innerWidth < 1200) {
    event.preventDefault();
    const heading = document.getElementById(anchor.hash.slice(1));
    context.addEventListener('hidden.bs.offcanvas', () => {
      heading.tabIndex = -1;
      heading.focus({preventScroll: true});
      heading.scrollIntoView({block: 'start'});
    }, {once: true});
    contextDrawer.hide();
  }
});
$('#branch-scenario').addEventListener('change', (event) => {
  branchScenario = event.target.value; branchCount = 2;
  expanded.add('root/demo');
  if (branchScenario === 'nested') expanded.add('root/team');
  buildTree();
});
$('#reset-demo').addEventListener('click', () => {
  branchScenario = 'normal'; branchCount = 2;
  expanded.clear(); expanded.add('root/architecture');
  $('#branch-scenario').value = 'normal';
  buildTree(); renderPage('root');
});
buildTree();
renderPage('root');
